actions.script:
// Accept either username or email for login
def loginIdentifier = username ?: email

// For development, accept any login
if (loginIdentifier && password) {
    success = true
    accessToken = "dev-token-" + System.currentTimeMillis()

    // Determine if loginIdentifier is email or username
    def isEmail = loginIdentifier.contains("@")
    def userEmail = isEmail ? loginIdentifier : loginIdentifier + "@example.com"
    def userName = isEmail ? loginIdentifier.split("@")[0] : loginIdentifier

    user = [
        userId: "EX_JOHN_DOE",
        email: userEmail,
        username: userName,
        displayName: "Development User"
    ]
    message = "Login successful"

    ec.logger.info("Development login successful for: ${loginIdentifier}")
} else {
    success = false
    message = "Username/email and password are required"
}

// For development, accept any registration
if (email && password) {
    success = true
    accessToken = "dev-token-" + System.currentTimeMillis()
    user = [
        userId: "USER_" + System.currentTimeMillis(),
        email: email,
        username: username ?: email.split("@")[0],
        displayName: username ?: email.split("@")[0]
    ]
    message = "Registration successful"

    ec.logger.info("Development registration successful for: ${email}")
} else {
    success = false
    message = "Email and password are required"
}
